example.code:
// 触发报警
var alarm = alarmHelper.Trigger("ALM001", "温度过高", AlarmLevel.Critical, "传感器1");

// 确认报警
alarmHelper.Acknowledge(alarm.Id, "操作员张三", "已处理");

// 恢复报警
alarmHelper.Recover(alarm.Id);

// 注册错误码
errorCodeManager.Register(new ErrorCodeInfo
{
    Code = "E1001",
    Category = "Database",
    Severity = ErrorSeverity.Error,
    DefaultMessage = "数据库连接失败",
    LocalizedMessages = new Dictionary<string, string>
    {
        ["zh-CN"] = "数据库连接失败: {0}",
        ["en-US"] = "Database connection failed: {0}"
    }
});

// 获取本地化消息
var message = errorCodeManager.GetMessage("E1001", args: "超时");

services.AddLoggingDiagnostics(options => {
    options.Log.MinimumLevel = LogLevel.Debug;
    options.Trace.Enabled = true;
    options.Alarm.EnableSound = false;
    options.Performance.CollectionIntervalSeconds = 10;
});

// 直接创建
var exportHelper = new LogExportHelper("logs");

// 导出到文本文件
var count = await exportHelper.ExportLogsAsync("export.txt", startDate, endDate);

// 导出到CSV
var count = await exportHelper.ExportLogsToCsvAsync("export.csv", startDate, endDate);

// 获取统计信息
var stats = await exportHelper.GetStatisticsAsync(startDate, endDate);

// 使用依赖注入
services.AddLoggingDiagnostics(options => {
    options.Log.MinimumLevel = LogLevel.Debug;
    options.Log.LogDirectory = "logs";
});

// 直接创建
var logHelper = new LogHelper(Options.Create(new LogOptions()));
logHelper.Information("这是一条信息日志");
logHelper.Error("发生错误", exception);

// 启动监控
await performanceMonitor.StartAsync();

// 获取当前系统信息
var systemInfo = await performanceMonitor.GetSystemInfoAsync();
Console.WriteLine($"CPU: {systemInfo.Cpu.TotalUsage:F1}%");
Console.WriteLine($"内存: {systemInfo.Memory.PhysicalMemoryUsage:F1}%");

// 监听性能告警
performanceMonitor.PerformanceAlert += (s, e) => {
    Console.WriteLine($"告警: {e.AlertType} - {e.Message}");
};

// 使用追踪作用域
using (traceHelper.BeginTrace("数据库查询"))
{
    // 执行数据库查询
}

// 追踪方法执行
var result = await traceHelper.TraceAsync("API调用", async ct => {
    return await httpClient.GetStringAsync(url, ct);
});
